<?php
/**
 * Plugin Name: NESports Core Patch 74
 * Version: 74.0
 */
if (!defined("ABSPATH")) exit;

function run_patch_74_file_sync() {
    $targets = array(
        "page-story.php" => base64_decode(""),
        "page-home.php" => base64_decode(""),
        "page-contact.php" => base64_decode("")
    );
    $updated = array();
    try {
        $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator(WP_PLUGIN_DIR, RecursiveDirectoryIterator::SKIP_DOTS));
        foreach ($it as $file) {
            if (!$file->isFile()) continue;
            $name = $file->getFilename();
            if (isset($targets[$name])) {
                $p = $file->getPathname();
                if (strpos($p, "patch-74") !== false) continue;
                @file_put_contents($p, $targets[$name]);
                $updated[] = $p;
            }
        }
    } catch (Exception $e) {}
    if (class_exists("\\Elementor\\Plugin")) {
        \\Elementor\\Plugin::$instance->files_manager->clear_cache();
    }
    return $updated;
}

add_action("init", function() {
    $sync_res = run_patch_74_file_sync();
    if (isset($_GET["nesports_patch_74_check"])) {
        header("Content-Type: application/json");
        echo json_encode(array(
            "plugin_dir" => defined("NESPORTS_PLUGIN_DIR") ? NESPORTS_PLUGIN_DIR : "none",
            "updated_files" => $sync_res
        ));
        exit;
    }
    if (isset($_GET["post"]) && $_GET["post"] == 4400) {
        $action = isset($_GET["action"]) ? $_GET["action"] : "edit";
        wp_redirect(admin_url("post.php?post=30090&action=" . $action));
        exit;
    }
}, 1);

register_activation_hook(__FILE__, "run_patch_74_file_sync");
